const contact = $input.first().json;
const proposal = $("GetApprovedChange").first().json;

const field = proposal.field_name;

if (!["phone", "company"].includes(field)) {
  throw new Error("Unsupported update field");
}

if (
  String(contact.id) !==
  String(proposal.hubspot_contact_id)
) {
  throw new Error("HubSpot contact ID mismatch");
}

const hubspotValue = String(
  contact.properties?.[field] ?? ""
).trim();

const baseline = String(
  proposal.current_value ?? ""
).trim();

const proposed = String(
  proposal.proposed_value ?? ""
).trim();

let action = "conflict";

if (hubspotValue === proposed) {
  action = "already_applied";
} else if (hubspotValue === baseline) {
  action = "apply";
}

return [{
  json: {
    ...proposal,
    hubspot_current_value: hubspotValue,
    action
  }
}];

const result = $input.first().json;
const proposal = $("EvaluateHubSpotChange").first().json;

if (String(result.id) !== String(proposal.hubspot_contact_id)) {
  throw new Error("Updated contact ID mismatch");
}

if (
  String(result.properties?.[proposal.field_name] ?? "").trim()
  !== String(proposal.proposed_value).trim()
) {
  throw new Error("HubSpot did not confirm the proposed value");
}

return [{
  json: {
    ...proposal,
    action: "applied"
  }
}];
